//! Exact-id parity between [`VitsTokenizer`] and HF `VitsTokenizer` on the
//! real `facebook/mms-tts-zlm` checkpoint.
//!
//! The fixture (`tests/fixtures/vits_tokenizer_zlm.json`) is checked in and
//! was generated by `crates/boostr-audio/tests/tools/vits_tokenizer_oracle/vits_tokenizer_oracle.py`.
//! The checkpoint directory itself is not checked in, so this test skips
//! unless `MMS_TTS_ZLM_DIR` or `BOOSTR_MODELS_DIR` points at it.

use boostr_audio::tts::VitsTokenizer;
use serde::Deserialize;

mod common;
use common::{load_json, model_fixture, skip_notice};

#[derive(Debug, Deserialize)]
struct Case {
    text: String,
    input_ids: Vec<u32>,
}

#[test]
fn matches_hf_vits_tokenizer_on_mms_tts_zlm() {
    let Some(checkpoint_dir) = model_fixture("MMS_TTS_ZLM_DIR", "facebook/mms-tts-zlm") else {
        skip_notice("facebook/mms-tts-zlm checkpoint", "MMS_TTS_ZLM_DIR");
        return;
    };

    let fixture_path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/vits_tokenizer_zlm.json"
    );
    let cases: Vec<Case> = load_json(std::path::Path::new(fixture_path));
    assert!(!cases.is_empty(), "fixture must not be empty");

    let tokenizer = VitsTokenizer::from_dir(&checkpoint_dir).expect("load VitsTokenizer");

    let mut failures = Vec::new();
    for case in &cases {
        let got = tokenizer
            .encode(&case.text)
            .unwrap_or_else(|e| panic!("encoding {:?}: {e}", case.text));
        if got != case.input_ids {
            failures.push(format!(
                "text {:?}: got {:?}, want {:?}",
                case.text, got, case.input_ids
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {} cases mismatched:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
